void _check(OliveParamSheet sheet, String name, List<String> header, List<List<String?>> rows) {
  expect(sheet.sheetName, name);
  expect(sheet.headers, header);
  expect(sheet.rows.length, rows.length);
  for (var i = 0; i < rows.length; i++) {
    expect(sheet.rows[i], rows[i], reason: 'satır ${i + 2}');
  }
}

void main() {
  test('PX sayfası Excel ile birebir aynı (32 satır, 20 sütun)', () {
    expect(pxParamSheet.rows.length, 32);
    expect(pxParamSheet.headers.length, 20);
    _check(pxParamSheet, _pxName, _pxHeader, _pxRows);
  });

  test('PXZ sayfası Excel ile birebir aynı (16 satır, 23 sütun)', () {
    expect(pxzParamSheet.rows.length, 16);
    expect(pxzParamSheet.headers.length, 23);
    _check(pxzParamSheet, _pxzName, _pxzHeader, _pxzRows);
  });

  test('her satırın hücre sayısı başlık sayısına eşit', () {
    for (final sheet in [pxParamSheet, pxzParamSheet]) {
      for (final r in sheet.rows) {
        expect(r.length, sheet.headers.length);
      }
    }
  });
}
